import { Dispatch, SetStateAction } from 'react';
import { NotificationOptions, CreateNotificationOptions } from './interfaces';

function createNotificationManager(setNotifications: Dispatch<SetStateAction<NotificationOptions[]>>) {
    let idx = 1;
    const intervalIds = new Map<number, any>();

    const removeInterval = (id: number) => {
        const intervalId = intervalIds.get(id);
        if (!intervalId) {
            return;
        }
        if (intervalId !== -1) {
            clearTimeout(intervalId);
        }
        intervalIds.delete(id);
    };

    const removeNotification = (id: number) => {
        const intervalId = intervalIds.get(id);
        if (!intervalId) {
            return;
        }
        removeInterval(id);
        return setNotifications((oldNotifications) => {
            return oldNotifications.filter(({ id: otherId }) => id !== otherId);
        });
    };

    const hideNotification = (id: number) => {
        // If the page is hidden, don't hide the notification with an animation because they get stacked.
        // This is to solve e.g. offline notifications appearing when the page is hidden, and when you focus
        // the tab again, they would be visible for the animation out even if they happened a while ago.
        if (document.hidden) {
            return removeNotification(id);
        }
        return setNotifications((oldNotifications) => {
            return oldNotifications.map((oldNotification) => {
                if (oldNotification.id !== id) {
                    return oldNotification;
                }
                return {
                    ...oldNotification,
                    isClosing: true,
                };
            });
        });
    };

    const createNotification = ({
        id = idx++,
        expiration = 3500,
        type = 'success',
        ...rest
    }: CreateNotificationOptions) => {
        if (intervalIds.has(id)) {
            throw new Error('notification already exists');
        }
        if (idx >= 1000) {
            idx = 0;
        }

        setNotifications((oldNotifications) => {
            const newNotification = {
                id,
                key: id,
                expiration,
                type,
                ...rest,
                isClosing: false,
            };
            if (typeof rest.text === 'string' && type !== 'success') {
                const duplicateOldNotification = oldNotifications.find(
                    (oldNotification) => oldNotification.text === rest.text
                );
                if (duplicateOldNotification) {
                    removeInterval(duplicateOldNotification.id);
                    return oldNotifications.map((oldNotification) => {
                        if (oldNotification === duplicateOldNotification) {
                            return {
                                ...newNotification,
                                key: duplicateOldNotification.key,
                            };
                        }
                        return oldNotification;
                    });
                }
            }
            return [...oldNotifications, newNotification];
        });

        intervalIds.set(id, expiration === -1 ? -1 : setTimeout(() => hideNotification(id), expiration));

        return id;
    };

    const clearNotifications = () => {
        intervalIds.forEach((intervalId) => {
            clearTimeout(intervalId);
        });

        intervalIds.clear();

        return setNotifications([]);
    };

    return {
        createNotification,
        removeNotification,
        hideNotification,
        clearNotifications,
    };
}

export type NotificationsManager = ReturnType<typeof createNotificationManager>;

export default createNotificationManager;
import { ReactNode } from 'react';

export type NotificationType = 'error' | 'warning' | 'info' | 'success';

export interface NotificationOptions {
    id: number;
    key: any;
    text: ReactNode;
    type: NotificationType;
    isClosing: boolean;
    disableAutoClose?: boolean;
}

export interface CreateNotificationOptions extends Omit<NotificationOptions, 'id' | 'type' | 'isClosing' | 'key'> {
    id?: number;
    type?: NotificationType;
    isClosing?: boolean;
    expiration?: number;
}

import React, { useContext } from 'react';
import NotificationsContext from './notificationsContext';
import NotificationsChildrenContext from './childrenContext';
import NotificationsContainer from './Container';

const NotificationsChildren = () => {
    const manager = useContext(NotificationsContext);
    const children = useContext(NotificationsChildrenContext);

    return (
        <NotificationsContainer
            notifications={children}
            removeNotification={manager.removeNotification}
            hideNotification={manager.hideNotification}
        />
    );
};

export default NotificationsChildren;
import Notification from './Notification';
import { NotificationOptions } from './interfaces';

interface Props {
    notifications: NotificationOptions[];
    removeNotification: (id: number) => void;
    hideNotification: (id: number) => void;
}
const NotificationsContainer = ({ notifications, removeNotification, hideNotification }: Props) => {
    const list = notifications.map(({ id, key, type, text, isClosing, disableAutoClose }) => {
        return (
            <Notification
                key={key}
                isClosing={isClosing}
                type={type}
                onClick={disableAutoClose ? undefined : () => hideNotification(id)}
                onExit={() => removeNotification(id)}
            >
                {text}
            </Notification>
        );
    });

    return <div className="notifications-container flex flex-column flex-align-items-center no-print">{list}</div>;
};

export default NotificationsContainer;
import { ReactNode, useState } from 'react';
import NotificationsContext from './notificationsContext';
import NotificationsChildrenContext from './childrenContext';
import { NotificationOptions } from './interfaces';
import createManager from './manager';
import { useInstance } from '../../hooks';

interface Props {
    children: ReactNode;
}

const NotificationsProvider = ({ children }: Props) => {
    const [notifications, setNotifications] = useState<NotificationOptions[]>([]);

    const manager = useInstance(() => {
        return createManager(setNotifications);
    });

    return (
        <NotificationsContext.Provider value={manager}>
            <NotificationsChildrenContext.Provider value={notifications}>
                {children}
            </NotificationsChildrenContext.Provider>
        </NotificationsContext.Provider>
    );
};

export default NotificationsProvider;
